// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalCoverageTest {

	@TempDir
	Path directory;

	@Test
	void retainsCoverageWhenDirtyPagesAreEvictedAndReloaded() throws Exception {
		int pageIds = 8192 * 8;
		int maxId = 3 * pageIds + 2;
		try (ValueStoreWalCoverage coverage = new ValueStoreWalCoverage(directory)) {
			// Three distant pages exceed the two-page cache, forcing dirty eviction before the prefix catches up.
			coverage.add(maxId);
			coverage.add(pageIds + 2);
			coverage.add(2 * pageIds + 2);
			coverage.add(maxId);
			assertThat(coverage.contiguousId()).isZero();
			for (int id = 1; id <= maxId; id++) {
				if (id != pageIds + 2 && id != 2 * pageIds + 2 && id != maxId) {
					coverage.add(id);
				}
			}
			assertThat(coverage.contiguousId()).isEqualTo(maxId);
			assertThat(coverage.maxId()).isEqualTo(maxId);
		}
		try (var files = Files.list(directory)) {
			assertThat(files).isEmpty();
		}
	}
}
